      "explanation": "“Bài nói ngắn (Elevator speech) là gì?”\n→ Là bài thuyết trình thuyết phục người nghe trong vòng chưa đầy 30 giây hoặc khoảng 100 từ. (A presentation that persuades the listener in less than thirty seconds, or around a hundred words.)\nBài nói ngắn được dùng để giới thiệu bản thân, ý tưởng hoặc sản phẩm một cách nhanh chóng, rõ ràng và ấn tượng – thường trong khoảng thời gian ngắn như khi đi cùng ai đó trong thang máy.",
