      "isMulti": false,
      "explanation": "“Từ ‘Logic’ trong tiếng Hy Lạp cổ logike có nghĩa là gì?”\n→ Khoa học hoặc nghệ thuật của lý luận. (The science or art of reasoning.)\nTừ “logic” bắt nguồn từ tiếng Hy Lạp logike, chỉ khả năng tư duy hợp lý và có hệ thống. Nó liên quan đến việc phân tích, đánh giá và đưa ra kết luận dựa trên lý lẽ và bằng chứng — nền tảng của tư duy phản biện và lập luận khoa học.",
