      "isMulti": false,
      "explanation": "“Ví dụ nào thể hiện rõ nhất về quyền lực đối trọng (Counterpower)?”\n→ B có các nguồn quyền lực khác để làm giảm ảnh hưởng từ quyền lực của A. (B has other sources of power to buffer the effects of A’s power.)\nQuyền lực đối trọng là khả năng của một cá nhân hoặc nhóm trong việc giảm thiểu hoặc cân bằng ảnh hưởng từ quyền lực của người khác. Khi B có các nguồn sức mạnh khác (như chuyên môn, mạng lưới quan hệ, hoặc quyền kiểm soát thông tin), họ có thể hạn chế tác động của A, từ đó duy trì sự độc lập và cân bằng quyền lực trong mối quan hệ.",
      "topic": "3. Teamwork, Leadership & Conflict",
      "images": []
