      "explanation": "“Câu hỏi ‘Điều gì tôi chưa thấy?’ (What don’t I see?) giúp bạn điều gì?”\n→ Giúp phát hiện ra các định kiến tiềm ẩn (Uncovering biases).\nKhi đặt câu hỏi này, bạn đang khuyến khích bản thân nhìn nhận thông tin từ nhiều góc độ khác nhau, nhận ra những giả định hoặc thành kiến có thể ảnh hưởng đến cách hiểu và đánh giá vấn đề. Đây là một phần quan trọng của tư duy phản biện, giúp mở rộng nhận thức và tiếp cận thông tin một cách khách quan hơn.",
