      "explanation": "“Mục tiêu chính của lộ trình nghề nghiệp (career roadmap) là gì?”\n→ Cung cấp hướng dẫn từng bước để tìm việc mới hoặc thay đổi con đường sự nghiệp (A step-by-step guide to searching for a new job or change career paths).\nLộ trình nghề nghiệp giúp cá nhân xác định mục tiêu nghề nghiệp, các bước cần thiết để đạt được chúng, cũng như chiến lược để phát triển hoặc chuyển hướng nghề nghiệp phù hợp với năng lực và sở thích của bản thân. Đây là công cụ quan trọng để định hướng tương lai nghề nghiệp một cách rõ ràng và có kế hoạch.",
