      "explanation": "Hàm ý nào sau đây được Mô hình Self-Evaluation Maintenance (SEM) gợi ý?\nC. Các nhà quản lý có thể thích tuyển những ứng viên chưa tối ưu vì họ ít có khả năng thách thức vị thế của mình trong tổ chức. Self-Evaluation Maintenance (SEM) Model của Abraham Tesser cho rằng con người luôn có xu hướng duy trì và bảo vệ sự đánh giá tích cực về bản thân (self-esteem) . Khi một người khác quá giỏi trong cùng lĩnh vực và có liên quan gần gũi với mình, họ có thể cảm thấy bị đe dọa và tìm cách giảm sự đe dọa đó.",
